B.a4r=new A.a2(B.jM,["Seviye 40","120 Ta\u015f, Kalas & Demir","0.18 \u015eam \xc7eli\u011fi / sn","1 Demir + 1 Obsidyen -> 1 \u015eam \xc7eli\u011fi"],t.w)
